package com.primehr.succession.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="succession_pool_decision",uniqueConstraints=@UniqueConstraint(name="uk_succ_pool_decision_assessment",columnNames={"agency_id","assessment_id"}))
public class SuccessionPoolDecision extends RspAuditedEntity{
 public enum Outcome{INCLUDED,NOT_INCLUDED}
 @Column(name="assessment_id",nullable=false,length=36)private String assessmentId;@Column(name="candidate_id",nullable=false,length=36)private String candidateId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Outcome outcome;@Column(name="readiness_level_id",nullable=false,length=36)private String readinessLevelId;@Column(name="readiness_level_code",nullable=false,length=80)private String readinessLevelCode;@Column(name="readiness_level_label",nullable=false,length=200)private String readinessLevelLabel;@Column(name="employee_visible_reason",nullable=false,length=4000)private String employeeVisibleReason;@Column(name="restricted_rationale",nullable=false,length=4000)private String restrictedRationale;@Column(name="decided_by",nullable=false,length=100)private String decidedBy;@Column(name="decided_at",nullable=false)private Instant decidedAt;@Column(name="effective_from")private LocalDate effectiveFrom;@Column(name="expires_on")private LocalDate expiresOn;
 protected SuccessionPoolDecision(){}public SuccessionPoolDecision(String a,SuccessionReadinessAssessment assessment,SuccessionReadinessLevel level,Outcome outcome,String employeeReason,String restrictedReason,String actor,Instant at,int validityMonths){super(a);assessmentId=assessment.getId();candidateId=assessment.getCandidateId();this.outcome=java.util.Objects.requireNonNull(outcome);readinessLevelId=level.getId();readinessLevelCode=level.getCode();readinessLevelLabel=level.getLabel();employeeVisibleReason=requiredText(employeeReason,"employeeVisibleReason");restrictedRationale=requiredText(restrictedReason,"restrictedRationale");decidedBy=requiredText(actor,"actor");decidedAt=at;if(outcome==Outcome.INCLUDED){if(!level.isAllowsPoolMembership())throw new IllegalArgumentException("Readiness level does not allow pool membership");if(validityMonths<1)throw new IllegalArgumentException("Membership validity must be positive");effectiveFrom=at.atZone(ZoneId.of("Asia/Manila")).toLocalDate();expiresOn=effectiveFrom.plusMonths(validityMonths).minusDays(1);}}
 public String getAssessmentId(){return assessmentId;}public String getCandidateId(){return candidateId;}public Outcome getOutcome(){return outcome;}public String getReadinessLevelId(){return readinessLevelId;}public String getReadinessLevelCode(){return readinessLevelCode;}public String getReadinessLevelLabel(){return readinessLevelLabel;}public String getEmployeeVisibleReason(){return employeeVisibleReason;}public String getRestrictedRationale(){return restrictedRationale;}public String getDecidedBy(){return decidedBy;}public Instant getDecidedAt(){return decidedAt;}public LocalDate getEffectiveFrom(){return effectiveFrom;}public LocalDate getExpiresOn(){return expiresOn;}
}
